public enum ContractError: Swift.Error {

    
    
    case UnsupportedSchemaVersion(version: String
    )
    case InvalidId(field: String, value: String
    )
    case EmptyField(name: String
    )
    case TargetFieldMissing(name: String
    )
    case PayloadMismatch(kind: SessionKind, expected: String
    )
    case UnsupportedAlgorithm(algorithm: String
    )
    case MissingExpiry
    case MissingScope
    case PlaceholderSignature
    case InvalidModuleHash
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeContractError: FfiConverterRustBuffer {
    typealias SwiftType = ContractError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ContractError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnsupportedSchemaVersion(
            version: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidId(
            field: try FfiConverterString.read(from: &buf), 
            value: try FfiConverterString.read(from: &buf)
            )
        case 3: return .EmptyField(
            name: try FfiConverterString.read(from: &buf)
            )
        case 4: return .TargetFieldMissing(
            name: try FfiConverterString.read(from: &buf)
            )
        case 5: return .PayloadMismatch(
            kind: try FfiConverterTypeSessionKind.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf)
            )
        case 6: return .UnsupportedAlgorithm(
            algorithm: try FfiConverterString.read(from: &buf)
            )
        case 7: return .MissingExpiry
        case 8: return .MissingScope
        case 9: return .PlaceholderSignature
        case 10: return .InvalidModuleHash

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ContractError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnsupportedSchemaVersion(version):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(version, into: &buf)
            
        
        case let .InvalidId(field,value):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(value, into: &buf)
            
        
        case let .EmptyField(name):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .TargetFieldMissing(name):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .PayloadMismatch(kind,expected):
            writeInt(&buf, Int32(5))
            FfiConverterTypeSessionKind.write(kind, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            
        
        case let .UnsupportedAlgorithm(algorithm):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(algorithm, into: &buf)
            
        
        case .MissingExpiry:
            writeInt(&buf, Int32(7))
        
        
        case .MissingScope:
            writeInt(&buf, Int32(8))
        
        
        case .PlaceholderSignature:
            writeInt(&buf, Int32(9))
        
        
        case .InvalidModuleHash:
            writeInt(&buf, Int32(10))
        
        }
    }
}


